from pathlib import Path
from html.parser import HTMLParser
import hashlib, json, re

class PageText(HTMLParser):
    def __init__(self):
        super().__init__()
        self.hidden = 0
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.hidden += 1

    def handle_endtag(self, tag):
        if tag in {'script', 'style'} and self.hidden:
            self.hidden -= 1

    def handle_data(self, data):
        text = ' '.join(data.split())
        if text and not self.hidden:
            self.parts.append(text)

root = Path('products/distribution/sqlite-gumroad-fit')
result = {}
patterns = {'pricing': r'fee|transaction|discover|monthly|processing', 'payouts': r'Canada|CAD|minimum|holding period|identity|verification|bank account|review'}
for name, pattern in patterns.items():
    path = root / 'raw' / f'{name}.html'
    raw = path.read_bytes()
    page = PageText()
    page.feed(raw.decode('utf-8', errors='replace'))
    passages = list(dict.fromkeys(' '.join(page.parts[max(0, i-1):i+2])[:800] for i, part in enumerate(page.parts) if re.search(pattern, part, re.I)))
    result[name] = {'source': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'passages': passages[:40], 'matched_passage_count': len(passages)}
output = root / 'director-pricing-payout-passages.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({key: value['matched_passage_count'] for key, value in result.items()}))
